INSERT INTO `user_knowledge_assessment` VALUES (21,1,34,'算法工程师','[{\"id\": 1, \"type\": \"单选\", \"answer\": [2], \"options\": [\"两个栈\", \"一个数组配合快速排序\", \"两个优先队列（堆）\", \"一个链表配合二分查找\"], \"question\": \"在处理一个实时数据流时，需要高效地维护一个动态集合，并支持快速查找当前集合中的最大值和最小值。以下哪种数据结构组合最适合此场景？\"}, {\"id\": 2, \"type\": \"多选\", \"answer\": [0, 1, 2, 3], \"options\": [\"时间复杂度\", \"空间复杂度\", \"图的顶点平均度数\", \"使用的递归深度\", \"缓存局部性\"], \"question\": \"在设计和分析一个图遍历算法（如用于社交网络好友推荐）时，下列哪些因素是需要重点考虑的算法复杂度指标？\"}, {\"id\": 3, \"type\": \"判断\", \"answer\": [0], \"options\": [\"正确\", \"错误\"], \"question\": \"对于一棵完全二叉树，使用数组进行存储比使用链表存储更节省空间，并且查找父节点和子节点的效率更高。\"}, {\"id\": 4, \"type\": \"单选\", \"answer\": [2], \"options\": [\"先使用归并排序（O(n log n)）排序整个数组，然后直接索引\", \"使用一个大小为K的最小堆，遍历数组进行维护\", \"使用快速选择算法（基于快速排序的分区思想）\", \"使用一个平衡二叉搜索树，依次插入所有元素\"], \"question\": \"要解决“在未排序的整数数组中找出第K大的元素”这一问题，并且要求平均时间复杂度尽可能低。以下哪种方法结合了合适的数据结构和算法思想？\"}, {\"id\": 5, \"type\": \"多选\", \"answer\": [0, 1, 3], \"options\": [\"栈的后进先出(LIFO)特性天然适合撤销操作的顺序\", \"如果还需要支持重做(Redo)功能，通常需要两个栈\", \"使用队列无法实现撤销功能\", \"栈的push和pop操作时间复杂度都是O(1)\", \"使用链表实现的栈比数组实现的栈在此场景下一定有性能优势\"], \"question\": \"在实现一个文本编辑器的撤销(Undo)功能时，通常可以使用栈来保存操作历史。以下关于此场景的叙述，哪些是正确的？\"}, {\"id\": 6, \"type\": \"判断\", \"answer\": [1], \"options\": [\"正确\", \"错误\"], \"question\": \"动态规划算法一定比递归的暴力解法具有更低的时间复杂度。\"}, {\"id\": 7, \"type\": \"单选\", \"answer\": [1], \"options\": [\"按开始时间升序排序，然后使用动态规划\", \"按结束时间升序排序，然后使用贪心选择\", \"按持续时间升序排序，然后使用深度优先搜索\", \"按开始时间降序排序，然后使用递归回溯\"], \"question\": \"现有一个任务调度问题，有n个任务，每个任务有开始时间和结束时间。目标是安排尽可能多的不重叠任务。一个高效的解决方案首先需要对任务按什么属性进行排序，然后主要应用了什么算法思想？\"}]','{\"1\": 0, \"2\": [0, 1], \"3\": 0, \"4\": 1, \"5\": [0], \"6\": 0, \"7\": 1}','[{\"type\": \"单选\", \"index\": 0, \"options\": [\"两个栈\", \"一个数组配合快速排序\", \"两个优先队列（堆）\", \"一个链表配合二分查找\"], \"question\": \"在处理一个实时数据流时，需要高效地维护一个动态集合，并支持快速查找当前集合中的最大值和最小值。以下哪种数据结构组合最适合此场景？\", \"correctAnswer\": [2], \"userAnswerText\": \"两个栈\", \"correctAnswerText\": \"两个优先队列（堆）\"}, {\"type\": \"多选\", \"index\": 1, \"options\": [\"时间复杂度\", \"空间复杂度\", \"图的顶点平均度数\", \"使用的递归深度\", \"缓存局部性\"], \"question\": \"在设计和分析一个图遍历算法（如用于社交网络好友推荐）时，下列哪些因素是需要重点考虑的算法复杂度指标？\", \"correctAnswer\": [0, 1, 2, 3], \"userAnswerText\": \"时间复杂度、空间复杂度\", \"correctAnswerText\": \"时间复杂度、空间复杂度、图的顶点平均度数、使用的递归深度\"}, {\"type\": \"单选\", \"index\": 3, \"options\": [\"先使用归并排序（O(n log n)）排序整个数组，然后直接索引\", \"使用一个大小为K的最小堆，遍历数组进行维护\", \"使用快速选择算法（基于快速排序的分区思想）\", \"使用一个平衡二叉搜索树，依次插入所有元素\"], \"question\": \"要解决“在未排序的整数数组中找出第K大的元素”这一问题，并且要求平均时间复杂度尽可能低。以下哪种方法结合了合适的数据结构和算法思想？\", \"correctAnswer\": [2], \"userAnswerText\": \"使用一个大小为K的最小堆，遍历数组进行维护\", \"correctAnswerText\": \"使用快速选择算法（基于快速排序的分区思想）\"}, {\"type\": \"多选\", \"index\": 4, \"options\": [\"栈的后进先出(LIFO)特性天然适合撤销操作的顺序\", \"如果还需要支持重做(Redo)功能，通常需要两个栈\", \"使用队列无法实现撤销功能\", \"栈的push和pop操作时间复杂度都是O(1)\", \"使用链表实现的栈比数组实现的栈在此场景下一定有性能优势\"], \"question\": \"在实现一个文本编辑器的撤销(Undo)功能时，通常可以使用栈来保存操作历史。以下关于此场景的叙述，哪些是正确的？\", \"correctAnswer\": [0, 1, 3], \"userAnswerText\": \"栈的后进先出(LIFO)特性天然适合撤销操作的顺序\", \"correctAnswerText\": \"栈的后进先出(LIFO)特性天然适合撤销操作的顺序、如果还需要支持重做(Redo)功能，通常需要两个栈、栈的push和pop操作时间复杂度都是O(1)\"}, {\"type\": \"判断\", \"index\": 5, \"options\": [\"正确\", \"错误\"], \"question\": \"动态规划算法一定比递归的暴力解法具有更低的时间复杂度。\", \"correctAnswer\": [1], \"userAnswerText\": \"正确\", \"correctAnswerText\": \"错误\"}]',NULL,'需要加强学习。共 7 题，答对 2 题，正确率 29%。','[{\"pointId\": 3, \"pointName\": \"栈与队列\", \"subjectName\": \"数据结构与算法\"}, {\"pointId\": 8, \"pointName\": \"算法复杂度分析\", \"subjectName\": \"数据结构与算法\"}, {\"pointId\": 7, \"pointName\": \"查找算法\", \"subjectName\": \"数据结构与算法\"}, {\"pointId\": 6, \"pointName\": \"排序算法\", \"subjectName\": \"数据结构与算法\"}, {\"pointId\": 9, \"pointName\": \"递归\", \"subjectName\": \"数据结构与算法\"}, {\"pointId\": 10, \"pointName\": \"动态规划\", \"subjectName\": \"数据结构与算法\"}]',29,'2','','2026-07-16 15:48:26','',NULL,'0');
